#!/usr/bin/env python3
from pathlib import Path


def replace_one(path, old, new):
    p = Path(path)
    s = p.read_text()
    n = s.count(old)
    if n != 1:
        raise SystemExit(f'FAIL: {path}: anchor count {n} != 1 for {old[:100]!r}')
    p.write_text(s.replace(old, new, 1))

